import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

// Interface para o item retornado pela RPC
interface RpcSimulacaoItem {
  loja_id: number;
  produto_master_id: number;
  produto_nome: string;
  setor: string;
  minimo_periodo: number;
  quantidade_atual: number;
  fonte: string;
}

// Interface para os dados de loja do Supabase
interface LojaSupabase {
  id: number;
  nome: string;
}

// Interface EXPORTADA para uma linha de produto pivotada
export interface LinhaMinimo {
  produtoMasterId: number;
  produtoNome: string;
  setor: string;
  colunas: Record<number, { minimo: number; atual: number; fonte: string }>;
}

// Interface EXPORTADA para o resultado do hook
export interface UseSimularMinimoPeriodoResult {
  lojas: Array<{ id: number; nome: string }>;
  linhas: LinhaMinimo[];
  totalPorProduto: Record<number, number>;
  isLoading: boolean;
  isError: boolean;
}

export function useSimularMinimoPeriodo(
  diaInicio: number,
  diasCobertura: number
): UseSimularMinimoPeriodoResult {
  // 1. Busca lojas ativas
  const {
    data: lojasData,
    isLoading: isLoadingLojas,
    isError: isErrorLojas,
  } = useQuery<LojaSupabase[]>({
    queryKey: ["lojas-ativas"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("lojas")
        .select("id,nome")
        .eq("ativo", true)
        .order("id");
      if (error) throw error;
      return data;
    },
  });

  // 2. Executa RPC de simulação
  const {
    data: rpcData,
    isLoading: isLoadingRpc,
    isError: isErrorRpc,
  } = useQuery<RpcSimulacaoItem[]>({
    queryKey: ["simular-minimo-periodo", diaInicio, diasCobertura],
    queryFn: async () => {
      const { data, error } = await (supabase.rpc as any)(
        "simular_minimo_periodo",
        { p_dia_inicio: diaInicio, p_dias_cobertura: diasCobertura }
      );
      if (error) throw error;
      return data;
    },
    enabled: diasCobertura >= 1 && diasCobertura <= 7,
  });

  const isLoading = isLoadingLojas || isLoadingRpc;
  const isError = isErrorLojas || isErrorRpc;

  // 3. Pivota dados memoizados para evitar re-execução a cada render do componente pai
  const { lojas, linhas, totalPorProduto } = useMemo(() => {
    const lojas: Array<{ id: number; nome: string }> = [];
    const linhas: LinhaMinimo[] = [];
    const totalPorProduto: Record<number, number> = {};

    if (rpcData && lojasData) {
      const lojasMapById = new Map<number, LojaSupabase>();
      lojasData.forEach((loja) => lojasMapById.set(loja.id, loja));

      const linhasMap = new Map<number, LinhaMinimo>();
      const lojasPresentesIds = new Set<number>();

      rpcData.forEach((item) => {
        // Coleta IDs das lojas presentes nos resultados da RPC
        lojasPresentesIds.add(item.loja_id);

        // Calcula o total por produto
        totalPorProduto[item.produto_master_id] =
          (totalPorProduto[item.produto_master_id] || 0) + item.minimo_periodo;

        // Pivota os dados para LinhaMinimo
        let linha = linhasMap.get(item.produto_master_id);
        if (!linha) {
          linha = {
            produtoMasterId: item.produto_master_id,
            produtoNome: item.produto_nome,
            setor: item.setor,
            colunas: {},
          };
          linhasMap.set(item.produto_master_id, linha);
        }
        linha.colunas[item.loja_id] = {
          minimo: item.minimo_periodo,
          atual: item.quantidade_atual,
          fonte: item.fonte,
        };
      });

      // Converte o mapa de linhas para array e ordena
      linhas.push(...Array.from(linhasMap.values()));
      linhas.sort((a, b) => {
        if (a.setor < b.setor) return -1;
        if (a.setor > b.setor) return 1;
        if (a.produtoNome < b.produtoNome) return -1;
        if (a.produtoNome > b.produtoNome) return 1;
        return 0;
      });

      // Converte o set de lojas presentes para array e ordena
      const sortedLojasIds = Array.from(lojasPresentesIds).sort((a, b) => a - b);
      sortedLojasIds.forEach((lojaId) => {
        const lojaInfo = lojasMapById.get(lojaId);
        if (lojaInfo) {
          lojas.push({ id: lojaInfo.id, nome: lojaInfo.nome });
        }
      });
    }

    return { lojas, linhas, totalPorProduto };
  }, [rpcData, lojasData]);

  return {
    lojas,
    linhas,
    totalPorProduto,
    isLoading,
    isError,
  };
}

