1	/**
2	 * @module useSetores.test
3	 *
4	 * Testes unitários do hook useSetores.
5	 * Cobrem: excluirSetor (bloqueio e deleção), criarSetor (normalização +
6	 * deduplicação) e atualizarProdutoSetorUnidade (campos corretos).
7	 */
8	
9	import { createElement, type ReactNode } from 'react';
10	import { renderHook, act, waitFor } from '@testing-library/react';
11	import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
12	import { describe, it, expect, vi, beforeEach } from 'vitest';
13	import { supabase } from '@/integrations/supabase/client';
14	import { useSetores } from './useSetores';
15	
16	// ─── helpers ────────────────────────────────────────────────────────────────
17	
18	function createWrapper() {
19	  const client = new QueryClient({
20	    defaultOptions: {
21	      queries: { retry: false, gcTime: 0 },
22	      mutations: { retry: false },
23	    },
24	  });
25	  return ({ children }: { children: ReactNode }) =>
26	    createElement(QueryClientProvider, { client }, children);
27	}
28	
29	/**
30	 * Configura o mock de supabase.from() para uma sequência de chamadas.
31	 * Cada entrada em `tableHandlers` é um mapa de nome-de-tabela para a
32	 * chain encadeável que esse .from() deve retornar.
33	 *
34	 * Usa mockImplementation para retornar builders diferentes conforme
35	 * a tabela solicitada.
36	 */
37	function setupFromMock(
38	  tableHandlers: Record<string, Record<string, unknown>>,
39	) {
40	  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(
41	    (table: string) => {
42	      return tableHandlers[table] ?? makeChain({});
43	    },
44	  );
45	}
46	
47	/** Constrói uma chain encadeável genérica que resolve para `result`. */
48	function makeChain(
49	  result: unknown,
50	  overrides: Record<string, unknown> = {},
51	): Record<string, unknown> {
52	  const chain: Record<string, unknown> = {
53	    select: vi.fn().mockReturnThis(),
54	    insert: vi.fn().mockReturnThis(),
55	    update: vi.fn().mockReturnThis(),
56	    delete: vi.fn().mockReturnThis(),
57	    upsert: vi.fn().mockReturnThis(),
58	    eq: vi.fn().mockReturnThis(),
59	    neq: vi.fn().mockReturnThis(),
60	    order: vi.fn().mockReturnThis(),
61	    limit: vi.fn().mockReturnThis(),
62	    head: vi.fn().mockReturnThis(),
63	    maybeSingle: vi.fn().mockResolvedValue(result),
64	    single: vi.fn().mockResolvedValue(result),
65	    then: (resolve: (v: unknown) => unknown) =>
66	      Promise.resolve(result).then(resolve),
67	    ...overrides,
68	  };
69	  return chain;
70	}
71	
72	// ─── testes ─────────────────────────────────────────────────────────────────
73	
74	describe('useSetores', () => {
75	  beforeEach(() => {
76	    vi.clearAllMocks();
77	  });
78	
79	  // ── A. excluirSetor ────────────────────────────────────────────────────────
80	
81	  describe('excluirSetor', () => {
82	    it('BLOQUEIA quando há itens ativos — retorna ok:false com contagem na mensagem e NÃO chama delete', async () => {
83	      // produtos_master: select com count retorna 3 ativos
84	      const produtosMasterChain: Record<string, unknown> = {
85	        select: vi.fn().mockReturnThis(),
86	        eq: vi.fn().mockReturnThis(),
87	        // A query termina sem .then explícito — a Promise é criada pelo then implícito.
88	        // Precisamos que a chain resolva { count: 3, error: null } quando awaited.
89	        then: (resolve: (v: unknown) => unknown) =>
90	          Promise.resolve({ count: 3, error: null }).then(resolve),
91	      };
92	
93	      // setores: não deve ser chamado (delete bloqueado)
94	      const setoresDeleteSpy = vi.fn();
95	      const setoresChain: Record<string, unknown> = {
96	        delete: setoresDeleteSpy,
97	        select: vi.fn().mockReturnThis(),
98	        eq: vi.fn().mockReturnThis(),
99	        order: vi.fn().mockReturnThis(),
100	        then: (resolve: (v: unknown) => unknown) =>
101	          Promise.resolve({ data: [], error: null }).then(resolve),
102	      };
103	
104	      setupFromMock({
105	        produtos_master: produtosMasterChain,
106	        setores: setoresChain,
107	      });
108	
109	      const { result } = renderHook(() => useSetores(), {
110	        wrapper: createWrapper(),
111	      });
112	
113	      let resultado: Awaited<ReturnType<typeof result.current.excluirSetor>>;
114	      await act(async () => {
115	        resultado = await result.current.excluirSetor('EMBALAGENS');
116	      });
117	
118	      expect(resultado!.ok).toBe(false);
119	      expect(resultado!.error).toMatch(/3/); // mensagem contém o número
120	      expect(setoresDeleteSpy).not.toHaveBeenCalled();
121	    });
122	
123	    it('deleta quando 0 itens ativos e retorna ok:true', async () => {
124	      const deleteSpy = vi.fn().mockReturnValue({
125	        eq: vi.fn().mockResolvedValue({ error: null }),
126	      });
127	
128	      // produtos_master count = 0
129	      const produtosMasterChain: Record<string, unknown> = {
130	        select: vi.fn().mockReturnThis(),
131	        eq: vi.fn().mockReturnThis(),
132	        then: (resolve: (v: unknown) => unknown) =>
133	          Promise.resolve({ count: 0, error: null }).then(resolve),
134	      };
135	
136	      // setores: delete encadeável que resolve sem erro
137	      const setoresChain: Record<string, unknown> = {
138	        select: vi.fn().mockReturnThis(),
139	        eq: vi.fn().mockReturnThis(),
140	        order: vi.fn().mockReturnThis(),
141	        delete: deleteSpy,
142	        then: (resolve: (v: unknown) => unknown) =>
143	          Promise.resolve({ data: [], error: null }).then(resolve),
144	      };
145	
146	      setupFromMock({
147	        produtos_master: produtosMasterChain,
148	        setores: setoresChain,
149	      });
150	
151	      const { result } = renderHook(() => useSetores(), {
152	        wrapper: createWrapper(),
153	      });
154	
155	      let resultado: Awaited<ReturnType<typeof result.current.excluirSetor>>;
156	      await act(async () => {
157	        resultado = await result.current.excluirSetor('VAZIO');
158	      });
159	
160	      expect(resultado!.ok).toBe(true);
161	      expect(deleteSpy).toHaveBeenCalled();
162	    });
163	  });
164	
165	  // ── B. criarSetor ──────────────────────────────────────────────────────────
166	
167	  describe('criarSetor', () => {
168	    it('normaliza para UPPERCASE antes de inserir', async () => {
169	      const insertSpy = vi.fn().mockResolvedValue({ error: null });
170	
171	      // maybeSingle retorna null (setor não existe)
172	      const setoresChain: Record<string, unknown> = {
173	        select: vi.fn().mockReturnThis(),
174	        eq: vi.fn().mockReturnThis(),
175	        order: vi.fn().mockReturnThis(),
176	        maybeSingle: vi.fn().mockResolvedValue({ data: null, error: null }),
177	        insert: insertSpy,
178	        then: (resolve: (v: unknown) => unknown) =>
179	          Promise.resolve({ data: [], error: null }).then(resolve),
180	      };
181	
182	      setupFromMock({ setores: setoresChain });
183	
184	      const { result } = renderHook(() => useSetores(), {
185	        wrapper: createWrapper(),
186	      });
187	
188	      await act(async () => {
189	        await result.current.criarSetor('embalagens especiais');
190	      });
191	
192	      // O insert deve ter sido chamado com o nome em UPPERCASE
193	      expect(insertSpy).toHaveBeenCalledWith(
194	        expect.objectContaining({ nome: 'EMBALAGENS ESPECIAIS', ativo: true }),
195	      );
196	    });
197	
198	    it('retorna ok:false quando setor ativo já existe (deduplicação)', async () => {
199	      const insertSpy = vi.fn();
200	
201	      const setoresChain: Record<string, unknown> = {
202	        select: vi.fn().mockReturnThis(),
203	        eq: vi.fn().mockReturnThis(),
204	        order: vi.fn().mockReturnThis(),
205	        // setor existente e ativo
206	        maybeSingle: vi.fn().mockResolvedValue({
207	          data: { nome: 'CÂMARA FRIA', ativo: true },
208	          error: null,
209	        }),
210	        insert: insertSpy,
211	        then: (resolve: (v: unknown) => unknown) =>
212	          Promise.resolve({ data: [], error: null }).then(resolve),
213	      };
214	
215	      setupFromMock({ setores: setoresChain });
216	
217	      const { result } = renderHook(() => useSetores(), {
218	        wrapper: createWrapper(),
219	      });
220	
221	      let resultado: Awaited<ReturnType<typeof result.current.criarSetor>>;
222	      await act(async () => {
223	        resultado = await result.current.criarSetor('CÂMARA FRIA');
224	      });
225	
226	      expect(resultado!.ok).toBe(false);
227	      expect(resultado!.error).toBe('Esse setor já existe.');
228	      expect(insertSpy).not.toHaveBeenCalled();
229	    });
230	
231	    it('retorna ok:false para nome vazio', async () => {
232	      const { result } = renderHook(() => useSetores(), {
233	        wrapper: createWrapper(),
234	      });
235	
236	      let resultado: Awaited<ReturnType<typeof result.current.criarSetor>>;
237	      await act(async () => {
238	        resultado = await result.current.criarSetor('   ');
239	      });
240	
241	      expect(resultado!.ok).toBe(false);
242	      expect(resultado!.error).toBe('Informe um nome.');
243	    });
244	  });
245	
246	  // ── C. atualizarProdutoSetorUnidade ────────────────────────────────────────
247	
248	  describe('atualizarProdutoSetorUnidade', () => {
249	    it('chama update em produtos_master com setor e unidade_medida — nenhum outro campo', async () => {
250	      // chain encadeável: .update(...).eq('id', x).eq('ativo', true) -> awaitable
251	      const eqChain: Record<string, unknown> = {};
252	      eqChain.eq = vi.fn().mockReturnValue(eqChain);
253	      eqChain.then = (resolve: (v: unknown) => unknown) =>
254	        Promise.resolve({ error: null }).then(resolve);
255	      const updateSpy = vi.fn().mockReturnValue(eqChain);
256	
257	      const produtosMasterChain: Record<string, unknown> = {
258	        select: vi.fn().mockReturnThis(),
259	        eq: vi.fn().mockReturnThis(),
260	        order: vi.fn().mockReturnThis(),
261	        update: updateSpy,
262	        then: (resolve: (v: unknown) => unknown) =>
263	          Promise.resolve({ data: [], error: null }).then(resolve),
264	      };
265	
266	      // setores chain para a query inicial do hook
267	      const setoresChain = makeChain({ data: [], error: null });
268	
269	      setupFromMock({
270	        produtos_master: produtosMasterChain,
271	        setores: setoresChain,
272	      });
273	
274	      const { result } = renderHook(() => useSetores(), {
275	        wrapper: createWrapper(),
276	      });
277	
278	      await act(async () => {
279	        await result.current.atualizarProdutoSetorUnidade(
280	          42,
281	          'EMBALAGENS',
282	          'un',
283	        );
284	      });
285	
286	      // update deve ter sido chamado SOMENTE com setor e unidade_medida
287	      expect(updateSpy).toHaveBeenCalledWith({
288	        setor: 'EMBALAGENS',
289	        unidade_medida: 'un',
290	      });
291	
292	      // garantir que não foi chamado com campos como ativo, nome ou outros
293	      const chamadaArgs = updateSpy.mock.calls[0][0] as Record<string, unknown>;
294	      expect(Object.keys(chamadaArgs)).toHaveLength(2);
295	      expect(chamadaArgs).not.toHaveProperty('ativo');
296	    });
297	
298	    it('retorna ok:true em caso de sucesso', async () => {
299	      const eqChain: Record<string, unknown> = {};
300	      eqChain.eq = vi.fn().mockReturnValue(eqChain);
301	      eqChain.then = (resolve: (v: unknown) => unknown) =>
302	        Promise.resolve({ error: null }).then(resolve);
303	
304	      const produtosMasterChain: Record<string, unknown> = {
305	        select: vi.fn().mockReturnThis(),
306	        eq: vi.fn().mockReturnThis(),
307	        order: vi.fn().mockReturnThis(),
308	        update: vi.fn().mockReturnValue(eqChain),
309	        then: (resolve: (v: unknown) => unknown) =>
310	          Promise.resolve({ data: [], error: null }).then(resolve),
311	      };
312	
313	      setupFromMock({
314	        produtos_master: produtosMasterChain,
315	        setores: makeChain({ data: [], error: null }),
316	      });
317	
318	      const { result } = renderHook(() => useSetores(), {
319	        wrapper: createWrapper(),
320	      });
321	
322	      let resultado: Awaited<
323	        ReturnType<typeof result.current.atualizarProdutoSetorUnidade>
324	      >;
325	      await act(async () => {
326	        resultado = await result.current.atualizarProdutoSetorUnidade(
327	          1,
