      // Deve ter chamado update com o setor correto
      expect(updateSpy).toHaveBeenCalledWith({ setor: 'EMBALAGENS' });

      // .in() deve ter recebido os ids
      const inSpy = (updateSpy.mock.results[0].value as { in: ReturnType<typeof vi.fn> }).in;
      expect(inSpy).toHaveBeenCalledWith('id', [1, 2]);

      // .eq('ativo', true) deve ter sido chamado
      expect(inChain.eq).toHaveBeenCalledWith('ativo', true);

      // .select('id') encadeado
      expect(selectFinalSpy).toHaveBeenCalledWith('id');

      // resultado correto
      expect(resultado!.ok).toBe(true);
      expect(resultado!.movidos).toBe(2);
    });
  });

  // ── E. query inicial ────────────────────────────────────────────────────────

  describe('query inicial', () => {
    it('retorna lista vazia sem crash quando banco retorna dados vazios', async () => {
      // Ambas as queries resolvem vazio
      const setoresChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      const produtosChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      setupFromMock({
        setores: setoresChain,
        produtos_master: produtosChain,
      });

      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      await waitFor(() => expect(result.current.isLoading).toBe(false));

      expect(result.current.setores).toEqual([]);
    });
  });
});

