/**
 * @module useZerarEstoque.test
 *
 * Testes unitários do hook useZerarEstoque.
 * Cobrem: zerarProduto (sucesso, input inválido, erro RPC), zerarSetor (sucesso,
 * input inválido), e invalidação de queries React Query após sucesso.
 *
 * Segue o padrão de useSetores.test.ts: renderHook + QueryClientProvider +
 * mock de supabase.rpc via setup.ts global.
 */

import { createElement, type ReactNode } from 'react';
import { renderHook, act, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { supabase } from '@/integrations/supabase/client';
import { useZerarEstoque } from './useZerarEstoque';

// ─── helpers ────────────────────────────────────────────────────────────────

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false },
    },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

// ─── testes ─────────────────────────────────────────────────────────────────

describe('useZerarEstoque', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ── A. zerarProduto — caminho feliz ────────────────────────────────────────

  describe('zerarProduto', () => {
    it('chama supabase.rpc com os parâmetros corretos e retorna data no sucesso', async () => {
      const rpcData = {
        ok: true,
        noop: false,
        saldo_anterior: 42,
        saldo_novo: 0,
        lotes_zerados: 3,
        etiquetas_resetadas: 2,
      };
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: rpcData,
        error: null,
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarProduto>>;
      await act(async () => {
        resultado = await result.current.zerarProduto(10, 2);
      });

      // RPC chamada com os parâmetros corretos
      expect(supabase.rpc).toHaveBeenCalledWith('zerar_estoque_produto', {
        p_produto_master_id: 10,
        p_loja_id: 2,
      });

      // Resultado espelha o data da RPC
      expect(resultado!.ok).toBe(true);
      expect(resultado!.saldo_anterior).toBe(42);
      expect(resultado!.saldo_novo).toBe(0);
      expect(resultado!.lotes_zerados).toBe(3);
      expect(resultado!.etiquetas_resetadas).toBe(2);
    });

    it('retorna ok:false e NÃO chama a RPC quando lojaId é inválido (null)', async () => {
      const rpcSpy = supabase.rpc as ReturnType<typeof vi.fn>;

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarProduto>>;
      await act(async () => {
        // @ts-expect-error testando propositalmente com null para cobrir o guard
        resultado = await result.current.zerarProduto(10, null);
      });

      expect(rpcSpy).not.toHaveBeenCalled();
      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBeTruthy();
    });

    it('retorna ok:false e NÃO chama a RPC quando produtoMasterId é 0', async () => {
      const rpcSpy = supabase.rpc as ReturnType<typeof vi.fn>;

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarProduto>>;
      await act(async () => {
        resultado = await result.current.zerarProduto(0, 2);
      });

      expect(rpcSpy).not.toHaveBeenCalled();
      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBeTruthy();
    });

    it('retorna ok:false com mensagem de erro quando a RPC retorna error não-nulo', async () => {
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: null,
        error: { message: 'Produto inexistente ou inativo' },
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarProduto>>;
      await act(async () => {
        resultado = await result.current.zerarProduto(999, 2);
      });

      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBe('Produto inexistente ou inativo');
    });

    it('no-op: retorna ok:true com noop:true quando RPC indica produto já zerado', async () => {
      const rpcData = {
        ok: true,
        noop: true,
        saldo_anterior: 0,
        lotes_zerados: 0,
        etiquetas_resetadas: 0,
      };
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: rpcData,
        error: null,
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarProduto>>;
      await act(async () => {
        resultado = await result.current.zerarProduto(5, 2);
      });

      expect(resultado!.ok).toBe(true);
      expect(resultado!.noop).toBe(true);
    });
  });

  // ── B. zerarSetor — caminho feliz e guards ─────────────────────────────────

  describe('zerarSetor', () => {
    it('chama supabase.rpc com os parâmetros corretos e retorna data no sucesso', async () => {
      const rpcData = {
        ok: true,
        setor: 'EMBALAGENS',
        produtos_no_setor: 5,
        produtos_zerados: 4,
        produtos_noop: 1,
        etiquetas_resetadas: 10,
        lotes_zerados: 8,
        erros: [],
      };
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: rpcData,
        error: null,
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarSetor>>;
      await act(async () => {
        resultado = await result.current.zerarSetor('EMBALAGENS', 2);
      });

      // RPC chamada com os parâmetros corretos
      expect(supabase.rpc).toHaveBeenCalledWith('zerar_estoque_setor', {
        p_setor_nome: 'EMBALAGENS',
        p_loja_id: 2,
      });

      expect(resultado!.ok).toBe(true);
      expect(resultado!.produtos_no_setor).toBe(5);
      expect(resultado!.produtos_zerados).toBe(4);
      expect(resultado!.produtos_noop).toBe(1);
    });

    it('retorna ok:false e NÃO chama a RPC quando setorNome é vazio', async () => {
      const rpcSpy = supabase.rpc as ReturnType<typeof vi.fn>;

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarSetor>>;
      await act(async () => {
        resultado = await result.current.zerarSetor('   ', 2);
      });

      expect(rpcSpy).not.toHaveBeenCalled();
      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBeTruthy();
    });

    it('retorna ok:false e NÃO chama a RPC quando lojaId é inválido (undefined)', async () => {
      const rpcSpy = supabase.rpc as ReturnType<typeof vi.fn>;

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarSetor>>;
      await act(async () => {
        // @ts-expect-error testando propositalmente com undefined para cobrir o guard
        resultado = await result.current.zerarSetor('DOCES', undefined);
      });

      expect(rpcSpy).not.toHaveBeenCalled();
      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBeTruthy();
    });

    it('retorna ok:false com erro quando a RPC retorna error', async () => {
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: null,
        error: { message: 'setor é obrigatório' },
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.zerarSetor>>;
      await act(async () => {
        resultado = await result.current.zerarSetor('DOCES', 2);
      });

      expect(resultado!.ok).toBe(false);
      expect(resultado!.erro).toBe('setor é obrigatório');
    });
  });

  // ── C. isZerando ───────────────────────────────────────────────────────────

  describe('isZerando', () => {
    it('começa em false', () => {
      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      expect(result.current.isZerando).toBe(false);
    });

    it('volta para false após a operação completar', async () => {
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: { ok: true, noop: false, saldo_anterior: 10, saldo_novo: 0 },
        error: null,
      });

      const { result } = renderHook(() => useZerarEstoque(), {
        wrapper: createWrapper(),
      });

      await act(async () => {
        await result.current.zerarProduto(1, 2);
      });

      await waitFor(() => expect(result.current.isZerando).toBe(false));
    });
  });

  // ── D. invalidação de queries após sucesso ─────────────────────────────────

  describe('invalidação de queries', () => {
    it('invalida a queryKey ["setores-gestao"] após zerarProduto com sucesso', async () => {
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: { ok: true, noop: false, saldo_anterior: 5, saldo_novo: 0 },
        error: null,
      });

      // QueryClient spy para capturar invalidateQueries
      const invalidateSpy = vi.fn().mockResolvedValue(undefined);
      const queryClient = new QueryClient({
        defaultOptions: { queries: { retry: false, gcTime: 0 } },
      });
      queryClient.invalidateQueries = invalidateSpy;

      const wrapper = ({ children }: { children: ReactNode }) =>
        createElement(QueryClientProvider, { client: queryClient }, children);

      const { result } = renderHook(() => useZerarEstoque(), { wrapper });

      await act(async () => {
        await result.current.zerarProduto(3, 2);
      });

      // Deve ter invalidado ['setores-gestao']
      expect(invalidateSpy).toHaveBeenCalledWith(
        expect.objectContaining({ queryKey: ['setores-gestao'] }),
      );
    });

    it('invalida a queryKey ["setores-gestao"] após zerarSetor com sucesso', async () => {
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: {
          ok: true,
          setor: 'DOCES',
          produtos_no_setor: 3,
          produtos_zerados: 3,
          produtos_noop: 0,
          erros: [],
        },
        error: null,
      });

      const invalidateSpy = vi.fn().mockResolvedValue(undefined);
      const queryClient = new QueryClient({
        defaultOptions: { queries: { retry: false, gcTime: 0 } },
      });
      queryClient.invalidateQueries = invalidateSpy;

      const wrapper = ({ children }: { children: ReactNode }) =>
        createElement(QueryClientProvider, { client: queryClient }, children);

      const { result } = renderHook(() => useZerarEstoque(), { wrapper });

      await act(async () => {
        await result.current.zerarSetor('DOCES', 2);
      });

      expect(invalidateSpy).toHaveBeenCalledWith(
        expect.objectContaining({ queryKey: ['setores-gestao'] }),
      );
    });

    it('NÃO invalida queries quando zerarProduto falha por input inválido', async () => {
      const invalidateSpy = vi.fn().mockResolvedValue(undefined);
      const queryClient = new QueryClient({
        defaultOptions: { queries: { retry: false, gcTime: 0 } },
      });
      queryClient.invalidateQueries = invalidateSpy;

      const wrapper = ({ children }: { children: ReactNode }) =>
        createElement(QueryClientProvider, { client: queryClient }, children);

      const { result } = renderHook(() => useZerarEstoque(), { wrapper });

      await act(async () => {
        // lojaId inválido — deve retornar antes de chamar RPC ou invalidar
        // @ts-expect-error testando guard
        await result.current.zerarProduto(10, null);
      });

      expect(invalidateSpy).not.toHaveBeenCalled();
    });
  });
});

