import { createElement, type ReactNode } from 'react';
import { renderHook, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { supabase } from '@/integrations/supabase/client';
import { useSimularMinimoPeriodo } from './useSimularMinimoPeriodo';

// ─── helpers ────────────────────────────────────────────────────────────────

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false },
    },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

/** Constrói uma chain encadeável genérica que resolve para `result` via .then(). */
function makeChain(
  result: unknown,
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  const chain: Record<string, unknown> = {
    select: vi.fn().mockReturnThis(),
    insert: vi.fn().mockReturnThis(),
    update: vi.fn().mockReturnThis(),
    delete: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    neq: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    maybeSingle: vi.fn().mockResolvedValue(result),
    single: vi.fn().mockResolvedValue(result),
    then: (resolve: (v: unknown) => unknown) =>
      Promise.resolve(result).then(resolve),
    ...overrides,
  };
  return chain;
}

/**
 * Configura o mock de supabase.from() para retornar chains diferentes por
 * nome de tabela. Tabelas não mapeadas resolvem para { data: [], error: null }.
 */
function setupFromMock(
  tableHandlers: Record<string, Record<string, unknown>>,
) {
  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(
    (table: string) =>
      tableHandlers[table] ?? makeChain({ data: [], error: null }),
  );
}

// ─── testes ─────────────────────────────────────────────────────────────────

describe('useSimularMinimoPeriodo', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ── A. Pivot multi-loja ──────────────────────────────────────────────────

  describe('pivot multi-loja', () => {
    it('1 produto em 2 lojas → 1 linha, colunas por loja_id, total = soma dos mínimos das 2 lojas', async () => {
      const lojasAtivas = [
        { id: 2, nome: 'Asa Sul' },
        { id: 3, nome: 'Asa Norte' },
      ];
      const rpcItems = [
        {
          loja_id: 2,
          produto_master_id: 10,
          produto_nome: 'Brownie',
          setor: 'DOCES',
          minimo_periodo: 5,
          quantidade_atual: 3,
          fonte: 'historico',
        },
        {
          loja_id: 3,
          produto_master_id: 10,
          produto_nome: 'Brownie',
          setor: 'DOCES',
          minimo_periodo: 8,
          quantidade_atual: 0,
          fonte: 'historico',
        },
      ];

      setupFromMock({
        lojas: makeChain({ data: lojasAtivas, error: null }),
      });
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: rpcItems,
        error: null,
      });

      const { result } = renderHook(
        () => useSimularMinimoPeriodo(1, 7),
        { wrapper: createWrapper() },
      );

      await waitFor(() => expect(result.current.isLoading).toBe(false));

      // Estrutura de lojas
      expect(result.current.lojas).toHaveLength(2);
      expect(result.current.lojas.map((l) => l.id)).toEqual([2, 3]);

      // Pivot: 1 linha com colunas por loja_id
      expect(result.current.linhas).toHaveLength(1);
      const linha = result.current.linhas[0];
      expect(linha.produtoNome).toBe('Brownie');
      expect(linha.setor).toBe('DOCES');
      expect(linha.colunas[2]).toEqual({
        minimo: 5,
        atual: 3,
        fonte: 'historico',
      });
      expect(linha.colunas[3]).toEqual({
        minimo: 8,
        atual: 0,
        fonte: 'historico',
      });

      // Total = soma das 2 lojas visíveis (5 + 8 = 13)
      expect(result.current.totalPorProduto[10]).toBe(13);
    });
