      // lojasData inclui apenas loja 2 (loja 99 não é ativa / não existe)
      const lojasAtivas = [{ id: 2, nome: 'Asa Sul' }];
      const rpcItems = [
        {
          loja_id: 2,
          produto_master_id: 10,
          produto_nome: 'Brownie',
          setor: 'DOCES',
          minimo_periodo: 5,
          quantidade_atual: 3,
          fonte: 'historico',
        },
        {
          // loja 99 existe nos dados da RPC mas não em lojasData
          loja_id: 99,
          produto_master_id: 10,
          produto_nome: 'Brownie',
          setor: 'DOCES',
          minimo_periodo: 20,
          quantidade_atual: 0,
          fonte: 'historico',
        },
      ];

      setupFromMock({
        lojas: makeChain({ data: lojasAtivas, error: null }),
      });
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: rpcItems,
        error: null,
      });

      const { result } = renderHook(
        () => useSimularMinimoPeriodo(1, 7),
        { wrapper: createWrapper() },
      );

      await waitFor(() => expect(result.current.isLoading).toBe(false));

      // Apenas loja 2 aparece nas colunas visíveis
      expect(result.current.lojas).toHaveLength(1);
      expect(result.current.lojas[0].id).toBe(2);

      // Total deve ser apenas 5 (loja 2), NÃO 25 (5 + 20 da loja 99)
      expect(result.current.totalPorProduto[10]).toBe(5);
    });
  });

  // ── C. Estado vazio ──────────────────────────────────────────────────────

  describe('estado vazio', () => {
    it('RPC retorna [] → linhas e lojas vazias, totalPorProduto vazio, sem crash', async () => {
      setupFromMock({
        lojas: makeChain({
          data: [{ id: 2, nome: 'Asa Sul' }],
          error: null,
        }),
      });
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: [],
        error: null,
      });

      const { result } = renderHook(
        () => useSimularMinimoPeriodo(1, 7),
        { wrapper: createWrapper() },
      );

      await waitFor(() => expect(result.current.isLoading).toBe(false));

      expect(result.current.linhas).toHaveLength(0);
      // lojasPresentesIds fica vazio quando rpcData é vazio
      expect(result.current.lojas).toHaveLength(0);
      expect(result.current.totalPorProduto).toEqual({});
      expect(result.current.isError).toBe(false);
    });
  });

  // ── D. Parâmetros passados à RPC ─────────────────────────────────────────

  describe('parâmetros da RPC', () => {
    it('chama simular_minimo_periodo com p_dia_inicio e p_dias_cobertura corretos', async () => {
      setupFromMock({
        lojas: makeChain({ data: [], error: null }),
      });
      (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        data: [],
        error: null,
      });

      const { result } = renderHook(
        () => useSimularMinimoPeriodo(2, 5),
        { wrapper: createWrapper() },
      );

      await waitFor(() => expect(result.current.isLoading).toBe(false));

      expect(supabase.rpc).toHaveBeenCalledWith('simular_minimo_periodo', {
        p_dia_inicio: 2,
        p_dias_cobertura: 5,
      });
    });
  });
});

